export function Code({children}:{children:string}){const[copied,setCopied]=useState(false);return <div className="dev-code"><button type="button" onClick={async()=>{try{await navigator.clipboard.writeText(children);setCopied(true);}catch{setCopied(false);}}}>{copied?'Copied':'Copy code'}</button><pre><code>{children}</code></pre></div>;}
export function ComponentReference({name}:{name:string}){
 const entry=api.components.find(component=>component.name===name);const[theme,setTheme]=useState<'dark'|'light'>('dark');if(!entry)return <p>Component reference unavailable.</p>;
 const Example=Examples[entry.example as keyof typeof Examples];const own=entry.props.filter(prop=>!prop.native),native=entry.props.filter(prop=>prop.native);
 const table=(rows:typeof entry.props)=><div className="dev-table"><table><thead><tr><th>Prop</th><th>Type / accepted values</th><th>Required / default</th><th>Meaning</th></tr></thead><tbody>{rows.map(prop=><tr key={prop.name}><td><code>{prop.name}</code></td><td><code>{prop.type}</code></td><td>{prop.required?'Required':prop.default??'Optional; no parameter default declared'}</td><td>{prop.description||'See the working example and linked implementation.'}</td></tr>)}</tbody></table></div>;
 return <main className="dev-doc"><p className="dev-kicker">React API · {api.version} · {entry.origin}</p><h1>{entry.name}</h1><p>{entry.usage}</p><p><a href={entry.sourceUrl}>Matching implementation</a> · <a href={entry.figmaUrl}>{entry.sourceNode?'Figma '+entry.sourceNode:'Original Figma file'}</a> · <a href="./?path=/story/developers-start-here--installation" target="_top">Install and theme the app</a></p><p className="dev-notice">Usable prototype implementation. Full original-Figma visual acceptance is pending. Extension APIs describe approved prototype patterns, not additional authored Figma variants. The Figma file link is file-level where a single component-node mapping is not established.</p><h2>Working React example</h2><p>Fictional sample content. The app supplies real data and business rules. Import the four stylesheets once and wrap your app in CromaProvider as shown in Start here.</p><label className="dev-theme">Example theme <select value={theme} onChange={event=>setTheme(event.target.value as 'dark'|'light')}><option value="dark">Dark</option><option value="light">Light</option></select></label><div className="dev-preview"><CromaProvider theme={theme} applyDocument={false} style={{padding:24}}><Example/></CromaProvider></div><p>Explicit Theme/Background props and fixed source artwork retain their own presentation. The selector cannot create an unauthored source variant.</p><h2>Copy into your React app</h2><Code>{entry.snippet}</Code><h2>Props and callbacks</h2><p>Generated from the public TypeScript API at this release. Required props can depend on a discriminated union such as single versus multiple selection. DOM defaults are browser defaults unless documented here.</p>{table(own)}{native.length>0&&<details><summary>Native React/HTML props</summary>{table(native)}<p>Additional supported native attributes are available in the installed TypeScript declarations. Refs are supported only by components exported with forwardRef.</p></details>}{entry.relatedTypes.length>0&&<><h2>Referenced data types</h2>{entry.relatedTypes.map(type=><details key={type.name}><summary>{type.name}</summary><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}><code>{type.declaration}</code></pre></details>)}</>}<h2>Behaviour and application boundary</h2><ul><li>Use callbacks to update controlled values. An event callback receives the native React event; value callbacks receive the value shown in their type.</li><li>Use native disabled/readOnly and error props where available. Source State/Visible forcing is for visual reference; omit it for normal interactions.</li><li>Keep requests, authentication, routing, validation policy, prices and eligibility outside presentation components.</li><li>Review keyboard focus, long content, loading, empty/error recovery and narrow layouts in your composed screen.</li></ul></main>;
}

