export const Installation:Story={render:()=> <main className="dev-doc"><p className="dev-kicker">Croma React developer guide · {version}</p><h1>Build with the Croma design system</h1><p>For React and React DOM 19. Node.js 22.12+ is required to develop this repository. The library supplies presentation and interaction; your React application owns services, routing and business rules.</p><h2>1. Install the matching release</h2><p>Run this in your React project. GitHub installation is supported; these packages are not on npmjs.com. Commit the resulting lockfile.</p><Code>{install}</Code><p><a href={`${root}/releases/tag/v${version}`}>Release {version} and downloads</a> · <a href={`${root}/blob/v${version}/CHANGELOG.md`}>Changelog</a> · <a href={root}>Editable source and contribution guide</a></p><h2>2. Apply fonts, tokens and the complete theme</h2><Code>{setup}</Code><p>CromaProvider applies the document background, text, browser colour scheme and full-height app region. Remove old body backgrounds and conflicting component overrides. For an embedded region, use applyDocument=false. Explicit Theme props win over inherited theme; fixed source artwork retains its original appearance.</p><h2>3. Choose a component before copying code</h2><p><a href="./?path=/story/developers-start-here--choose-components" target="_top">Choose components</a> distinguishes original Figma branches from shared prototype extensions. Open React API in the sidebar for a working example, public import, props and source links for each export.</p><h2>4. Connect data through the application</h2><p>Try <a href="./?path=/story/developers-api-and-forms--search-request" target="_top">API and forms</a> for a mocked HTTP search with failure/retry and a validated exchange form. No real account, purchase or eligibility request is sent.</p><h2>5. Check the composed screen</h2><p>Review wide/narrow layouts, keyboard navigation, long labels, validation, loading, empty and retry states. Use the Accessibility panel as a first check. Read <a href="./?path=/story/developers-start-here--quality-and-acceptance" target="_top">Quality and acceptance</a> for what the release checks and what remains unaccepted.</p></main>};
export const ChooseComponents:Story={render:()=> <main className="dev-doc"><h1>Choose the correct component</h1><p>Source branches are deliberately separate. The following choices are usage guidance for this code library, not changes to the original Figma file.</p><table><thead><tr><th>Design or task</th><th>Use</th><th>Rule</th></tr></thead><tbody><tr><td>Figma Filled / Outlined / Text button</td><td>Button</td><td>Retain Large/Small and source Theme. Icon and Segmented are specialised branches.</td></tr><tr><td>Figma Desktop / Mobile Primary / Secondary / Link</td><td>Local.Button</td><td>Use the exact source tuple. Do not equate Primary with Filled or Mobile with Small.</td></tr><tr><td>Shared prototype actions, loading and wrapping labels</td><td>PrototypeButton + ActionGroup</td><td>Use primary, secondary and quiet. Group Save and Continue at the trailing edge.</td></tr><tr><td>Original floating-label input</td><td>FormField</td><td>Use Label, native input props and errorText. Omit forced State.</td></tr><tr><td>Shared prototype form pattern</td><td>PrototypeField</td><td>Separate label, help and error. It is a documented extension, not the floating-label Figma branch.</td></tr><tr><td>Figma dropdown with a floating caption</td><td>FormDropdown</td><td>Use value/onChange. Default Dropdown retains its separate hidden-caption source.</td></tr><tr><td>Variant search and suggestions</td><td>SearchCombobox</td><td>Keep a stable selected variant ID. Clear it when query or filters change.</td></tr><tr><td>Finish pills or condition choices</td><td>SelectionPillGroup</td><td>Use pill/card and single/multiple. The app owns exclusions such as “No issues”.</td></tr><tr><td>Editable prototype navigation</td><td>CommerceHeader + Breadcrumb</td><td>Use LiveCommerceHeader only for the dated live-site composition. Header is a lower-level helper.</td></tr><tr><td>Content grouping</td><td>PlainSection / SurfaceCard</td><td>Plain sections are transparent. Cards own their inset. Nested cards become plain sections.</td></tr></tbody></table><h2>Public React API</h2><div className="dev-table"><table><thead><tr><th>Component</th><th>Origin</th><th>Usage</th></tr></thead><tbody>{api.components.map(entry=><tr key={entry.name}><td><a href={`./?path=/docs/react-api-${entry.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}--usage-and-source`} target="_top">{entry.name}</a></td><td>{entry.origin}</td><td>{entry.usage}</td></tr>)}</tbody></table></div></main>};
