export const SingleSelection:Story={render:function Single(){const[value,setValue]=useState('');return <div style={{maxWidth:760,display:'grid',gap:24}}><p>Prototype extension · Select one purchased phone.</p><SelectablePurchaseGroup label="Choose a purchased phone" description="Select the phone you want to exchange." items={purchases} value={value} onValueChange={setValue}/><output aria-live="polite">{value?'Phone chosen: '+purchases.find(p=>p.value===value)?.model:'No phone chosen'}</output></div>;}};
